+++ b/src/filesystem/__tests__/list-anchored.test.ts
@@ -0,0 +1,187 @@
+// Protocol-level tests that every listing reads the directory validation
+// resolved, as every read does (read-anchored.test.ts). The race a client can
+// win against a listing is staged deterministically: right after validation
+// realpath's the listed directory, it is swapped for a symlink to a directory
+// outside the allowed one, and swapped back before the next path under it is
+// validated (the racer's rename back). Before listings were anchored, each of
+// these returned the outside directory's entry names.
+
+import fs from "fs/promises";
+import fsSync from "fs";
+import path from "path";
+import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
+import { type Client } from "@modelcontextprotocol/client";
+import {
+  call,
+  connect,
+  makeTempDir,
+  quietStderr,
+  textOf,
+  type Connected,
+} from "./helpers.js";
+
+// The name of the one entry outside, so a listing of it shows.
+const OUTSIDE_NAME = "outside-entry-0123456789.txt";
+
+let dir: string;
+let outside: string;
+let flip: string;
+let flipReal: string;
+let conn: Connected;
+let client: Client;
+
+beforeEach(async () => {
+  quietStderr();
+  dir = await makeTempDir("mcp-fs-list-anchor-");
+  outside = await makeTempDir("mcp-fs-list-anchor-outside-");
+  flip = path.join(dir, "flip");
+  flipReal = path.join(dir, "flip-real");
+  await fs.mkdir(flip);
+  await fs.writeFile(path.join(flip, "inside.txt"), "inside\n");
+  await fs.writeFile(path.join(outside, OUTSIDE_NAME), "outside\n");
+  conn = await connect([dir]);
+  client = conn.client;
+});
+
+afterEach(async () => {
+  vi.restoreAllMocks();
+  await conn.close();
+  await fs.rm(dir, { recursive: true, force: true });
+  await fs.rm(outside, { recursive: true, force: true });
+});
+
+/** Swap `flip` for a symlink to `outside`. */
+function swapDirectory(): void {
+  fsSync.renameSync(flip, flipReal);
+  fsSync.symlinkSync(outside, flip);
+}
+
+/** Put the real `flip` back. */
+function swapBack(): void {
+  fsSync.unlinkSync(flip);
+  fsSync.renameSync(flipReal, flip);
+}
+
+/**
+ * Swap `flip` out right after validation realpath's it, and back just before
+ * a path under it is realpath'd, as a racer renaming it back and forth would.
+ */
+function raceFlip(): void {
+  const realRealpath = fs.realpath.bind(fs);
+  let state: "before" | "swapped" | "back" = "before";
+  vi.spyOn(fs, "realpath").mockImplementation(async (p, opts) => {
+    if (state === "swapped" && String(p).startsWith(flip + path.sep)) {
+      state = "back";
+      swapBack();
+    }
+    const resolved = await realRealpath(p, opts);
+    if (state === "before" && p === flip) {
+      state = "swapped";
+      swapDirectory();
+    }
+    return resolved;
+  });
+}
+
+const DIRECTORY_CHANGED = /Access denied - a directory on the path changed/;
+
+describe.skipIf(process.platform === "win32")(
+  "a listed directory swapped for a symlink after validation",
+  () => {
+    it.each([
+      ["list_directory", {}],
+      ["list_directory_with_sizes", {}],
+      ["directory_tree", {}],
+      ["search_files", { pattern: "*" }],
+    ])("%s does not list through it", async (tool, extra) => {
+      raceFlip();
+      const result = await call(client, tool, { path: flip, ...extra });
+      expect(result.isError).toBe(true);
+      expect(textOf(result)).toMatch(DIRECTORY_CHANGED);
+      expect(JSON.stringify(result)).not.toContain(OUTSIDE_NAME);
+    });
+
+    it("directory_tree does not descend through a subdirectory swapped after validation", async () => {
+      raceFlip();
+      const result = await call(client, "directory_tree", { path: dir });
+      expect(result.isError).toBe(true);
+      expect(textOf(result)).toMatch(DIRECTORY_CHANGED);
+      expect(JSON.stringify(result)).not.toContain(OUTSIDE_NAME);
+    });
+
+    it("search_files skips, and reports, a subdirectory swapped after validation", async () => {
+      raceFlip();
+      const result = await call(client, "search_files", {
+        path: dir,
+        pattern: "**",
